import {useState} from "react";

function Square(){
  const [value, setValue]=useState[null];

  function handleClick(){
    setValue("x");
  }
  return (
    <button classname="square" onClick={handleClick}>{value}</button>
  )
}

export default function Board(){
  return ( 
    <>
    <div>
       <Square />
       <Square />
       <Square />
    </div>
    <div>
       <Square />
       <Square />
       <Square />
    </div>
    <div>
       <Square />
       <Square />
       <Square />
    </div>
   
    </>
       
  
  )
}
